1	// Package known persists a sorted, deduplicated list of Crow module
2	// addresses the user has successfully diff'd or browsed, so future
3	// invocations can offer shell-completion and TUI suggestions.
4	//
5	// The on-disk format is plain text, one ns/name/provider per line,
6	// alphabetically sorted, with a trailing newline. Empty or missing
7	// file means "no suggestions yet" — not an error.
8	//
9	// Concurrent writers: last writer wins. Two birdseye processes running
10	// simultaneously may each see the file before the other's Rename
11	// lands; whichever Rename completes last sets the final contents.
12	// Acceptable for a low-frequency, append-only-ish list.
13	package known
14	
15	import (
16		"bufio"
17		"fmt"
18		"os"
19		"path/filepath"
20		"sort"
21		"strings"
22	
23		"github.com/immuta/operations/services/crow/pkg/api"
24	)
25	
26	// Path returns the default known-modules file path, honoring
27	// os.UserConfigDir() (XDG_CONFIG_HOME on Linux, Application Support on
28	// macOS). The directory is NOT created here — Add creates it lazily on
29	// first write.
30	func Path() (string, error) {
31		cfg, err := os.UserConfigDir()
32		if err != nil {
33			return "", fmt.Errorf("resolve user config dir: %w", err)
34		}
35		return filepath.Join(cfg, "birdseye", "known-modules"), nil
36	}
37	
38	// Load reads the file at path. Returns an empty slice if the file
39	// does not exist (first run is normal). Lines failing the
40	// ns/name/provider validation are silently skipped. The result is
41	// sorted ascending.
42	func Load(path string) ([]string, error) {
43		f, err := os.Open(path)
44		if err != nil {
45			if os.IsNotExist(err) {
46				return nil, nil
47			}
48			return nil, fmt.Errorf("open known-modules: %w", err)
49		}
50		defer f.Close()
51	
52		var out []string
53		scanner := bufio.NewScanner(f)
54		for scanner.Scan() {
55			line := strings.TrimSpace(scanner.Text())
56			if line == "" {
57				continue
58			}
59			if !validAddress(line) {
60				continue
61			}
62			out = append(out, line)
63		}
64		if err := scanner.Err(); err != nil {
65			return nil, fmt.Errorf("scan known-modules: %w", err)
66		}
67		sort.Strings(out)
68		return out, nil
69	}
70	
71	// Add inserts address into the file at path. Existing entries are
72	// preserved; duplicates deduplicated; the final list is sorted.
73	// Writes are atomic via temp file + rename in the same directory.
74	// The directory is created with 0o755 if missing. If address is not a
75	// well-formed ns/name/provider triple, Add returns an error without
76	// touching the file.
77	func Add(path, address string) error {
78		if !validAddress(address) {
79			return fmt.Errorf("invalid module address %q", address)
80		}
81		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
82			return fmt.Errorf("mkdir known-modules dir: %w", err)
83		}
84	
85		existing, err := Load(path)
86		if err != nil {
87			return err
88		}
89		merged := mergeAndSort(existing, address)
90	
91		tmp, err := os.CreateTemp(filepath.Dir(path), ".known-modules-*.tmp")
92		if err != nil {
93			return fmt.Errorf("create temp: %w", err)
94		}
95		tmpName := tmp.Name()
96		w := bufio.NewWriter(tmp)
97		for _, addr := range merged {
98			if _, err := w.WriteString(addr); err != nil {
99				_ = tmp.Close()
100				_ = os.Remove(tmpName)
101				return fmt.Errorf("write temp: %w", err)
102			}
103			if err := w.WriteByte('\n'); err != nil {
104				_ = tmp.Close()
105				_ = os.Remove(tmpName)
106				return fmt.Errorf("write temp: %w", err)
107			}
108		}
109		if err := w.Flush(); err != nil {
110			_ = tmp.Close()
111			_ = os.Remove(tmpName)
112			return fmt.Errorf("flush temp: %w", err)
113		}
114		if err := tmp.Close(); err != nil {
115			_ = os.Remove(tmpName)
116			return fmt.Errorf("close temp: %w", err)
117		}
118		if err := os.Rename(tmpName, path); err != nil {
119			_ = os.Remove(tmpName)
120			return fmt.Errorf("rename temp: %w", err)
121		}
122		return nil
123	}
124	
125	// mergeAndSort returns a deduplicated, sorted slice combining existing
126	// with the new address.
127	func mergeAndSort(existing []string, address string) []string {
128		seen := make(map[string]struct{}, len(existing)+1)
129		out := make([]string, 0, len(existing)+1)
130		for _, a := range existing {
131			if _, dup := seen[a]; dup {
132				continue
133			}
134			seen[a] = struct{}{}
135			out = append(out, a)
136		}
137		if _, dup := seen[address]; !dup {
138			out = append(out, address)
139		}
140		sort.Strings(out)
141		return out
142	}
143	
144	// validAddress checks that s is exactly three slash-separated segments
145	// each passing api.ValidateSegments.
146	func validAddress(s string) bool {
147		parts := strings.Split(s, "/")
148		if len(parts) != 3 {
149			return false
150		}
151		return api.ValidateSegments(parts) == nil
152	}
